# frozen_string_literal: true

require "base64"
require "json"
require "zlib"

# Compact data only: [level, name, school, ritual]. It was transcribed from the
# PHB 2014 class lists; full spell text is deliberately not included.
module PlayerHandbook2014SpellLists
  DATA = ""

  def self.by_class
    @by_class ||= JSON.parse(Zlib::Inflate.inflate(Base64.decode64(DATA)))
  end
end
